// General-purpose C#/.NET architecture teaching material. No project-specific rules.
static partial class Curriculum
{
    private static Lesson[] BuildModernArchitectureLessons() =>
    [
        new("arch-dependency-direction", "Architecture & boundaries", 1, "Enforce inward dependencies", "Point source dependencies toward business rules so frameworks and databases stay replaceable details.", "Clean Architecture organizes source dependencies around stable business policy. Domain is the center, Application coordinates use cases, Infrastructure implements external interfaces, and the API (presentation) layer handles transport such as HTTP.", "Domain references no web framework, ORM, messaging library, or infrastructure package. Application depends on Domain and declares ports such as IOrderRepository. Infrastructure depends on Application/Domain and implements ports. The API references Application; Infrastructure is wired only at the composition root. A dependency rule is a compile-time reference rule, not necessarily the direction of runtime calls. When compilation seems to require a new outward reference, introduce an inward-facing interface or reconsider the boundary rather than bypassing it.", "Domain ← Application ← API\\n         ↑\\n Infrastructure (implements Application ports)", new Exercise(ExerciseKind.Presentation, "Practice the design", "Trace references in a four-project solution and explain why Application importing Infrastructure is a violation.", ["Work through the scenario before continuing", "Compare the alternatives and their consequences"], null, null, [], "Sketch the types and trace how a request flows across the boundaries.", []), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures")),
        new("arch-ports-and-composition", "Architecture & boundaries", 2, "Implement ports at the boundary", "Let use cases depend on interfaces they own, and choose concrete implementations in one place.", "An application port is an interface describing an external capability that a use case needs; an adapter implements that interface using a real dependency.", "Put IOrderRepository in Application (or Domain if the domain truly owns that abstraction) and EfOrderRepository in Infrastructure. Inject the port into a handler. Register the concrete adapter in Program.cs or an Infrastructure AddInfrastructure extension called only by composition code. API endpoints should not construct adapters or reference their concrete types. Verify project references automatically with architecture tests such as NetArchTest or ArchUnitNET.", "public sealed class PlaceOrderHandler(IOrderRepository orders) { /* use orders */ }\\n// Program.cs: services.AddScoped<IOrderRepository, EfOrderRepository>();", new Exercise(ExerciseKind.MultipleChoice, "Check your understanding", "Which choice best follows the lesson?", ["Choose one answer"], null, "correct", [new Choice("correct", "Sketch an architecture test that fails when Domain references EF Core or when Application references Infrastructure."), new Choice("incorrect", "Bypass the layer boundary to make a controller or handler compile."), new Choice("other", "Ignore the rule and rely on the UI to enforce it.")], "Choose the design that preserves the appropriate boundary and explicitly handles failures.", ["Explains the design tradeoff"]), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/dotnet/core/extensions/dependency-injection")),
        new("ddd-contexts", "Domain-Driven Design", 3, "Define bounded contexts and ubiquitous language", "Draw model boundaries where the meaning of business words changes.", "A bounded context is a boundary where domain terminology and rules have one consistent meaning. An aggregate is a consistency boundary inside a context.", "Group features by business capability (for example Catalog and Ordering), keeping each context's entities, value objects, events, and use cases near one another. Separate bounded contexts by IDs, integration/domain events and explicit application contracts. Never reach inside another context's aggregate object. Translate terminology at context boundaries rather than forcing a shared mega-model. A domain event records something that happened; publishing across process boundaries often needs an outbox.", "Ordering/Orders/{Order.cs,OrderId.cs,OrderPlaced.cs}\\nCatalog/Products/{Product.cs,ProductId.cs}", new Exercise(ExerciseKind.Presentation, "Practice the design", "Draw two contexts and identify which concepts may cross their boundary safely.", ["Work through the scenario before continuing", "Compare the alternatives and their consequences"], null, null, [], "Sketch the types and trace how a request flows across the boundaries.", []), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/ddd-oriented-microservice")),
        new("ddd-aggregates-values", "Domain-Driven Design", 4, "Protect aggregates, values and invariants", "Keep each business rule enforced by one object that cannot be put into an invalid state.", "An aggregate root is the only entry point for mutations across a consistency boundary. A value object is defined by its values rather than identity.", "Expose read-only collections and private setters/backing fields; change the aggregate through meaningful methods. Other aggregates are referenced by ID. Enforce invariants in constructors/factories and each transition; rejected states must not escape. Prefer sealed record or readonly record struct for immutable value objects when appropriate, and validate value object construction (Money cannot have unsupported currency, Quantity cannot be negative). Domain services handle rules that do not naturally fit one entity. Raise domain events from the aggregate; do not send email or publish to a broker directly from domain code. Domain invariants are separate from boundary DTO shape validation.", "public readonly record struct Quantity(int Value)\\n{\\n    public static Quantity Create(int value) => value >= 0 ? new(value) : throw new DomainException(\"quantity.invalid\");\\n}", new Exercise(ExerciseKind.MultipleChoice, "Check your understanding", "Which choice best follows the lesson?", ["Choose one answer"], null, "correct", [new Choice("correct", "Implement AddLine(ProductId, Quantity) on an Order root; forbid public line-item mutation."), new Choice("incorrect", "Bypass the layer boundary to make a controller or handler compile."), new Choice("other", "Ignore the rule and rely on the UI to enforce it.")], "Choose the design that preserves the appropriate boundary and explicitly handles failures.", ["Explains the design tradeoff"]), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/microservice-domain-model")),
        new("cqrs-requests", "CQRS & MediatR", 5, "Separate commands and queries", "Separate code that changes state from code that reads it, and decide whether a mediator earns its cost.", "CQRS means Command Query Responsibility Segregation: commands request state changes, while queries return data without changing state. MediatR is an optional in-process dispatcher, not a requirement of CQRS.", "A common implementation represents each use case as one command or query type with one handler, dispatched by an in-process mediator such as MediatR (ISender.Send(request, ct)) or called directly as an application service. Either way, endpoints delegate to the use case rather than calling repositories themselves. Command handlers orchestrate load aggregate → call domain method → save, while query handlers project read DTOs. Avoid burying business rules in handlers or a generic Services grab bag. A mediator adds indirection: it makes cross-cutting pipelines easy but hides the call graph from navigation tools. It also has a cost: MediatR v13 and later are commercially licensed (free under a revenue threshold and for education and non-production use), while older versions keep their original license. Many teams use plain application services and decorators instead; choose deliberately.", "public sealed record ShipOrder(Guid Id) : IRequest;\\npublic sealed class Handler(IOrderRepository orders) : IRequestHandler<ShipOrder> { /* load, Ship, save */ }", new Exercise(ExerciseKind.Presentation, "Practice the design", "Trace one command and one query, labeling which may change persistent state.", ["Work through the scenario before continuing", "Compare the alternatives and their consequences"], null, null, [], "Sketch the types and trace how a request flows across the boundaries.", []), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://github.com/jbogard/MediatR")),
        new("cqrs-pipelines-transactions", "CQRS & MediatR", 6, "Keep policies in pipeline behaviors", "Apply validation, logging and transactions once, around every request, instead of in each handler.", "A pipeline behavior wraps a request handler to apply a reusable concern before or after handling.", "Apply cross-cutting policies once: input validation, structured logging, and a transaction around each write command. With a mediator these are pipeline behaviors; without one, use decorators or endpoint filters. Queries never deliberately mutate state. Save events with state and a durable outbox in the same transaction; dispatch asynchronously afterward. Consider concurrency tokens/version columns for conflicting aggregate writes and idempotency keys for retried commands. Do not open remote network calls inside a database transaction. Tests should prove validation short-circuits and rollback happens on failure.", "request → validation → logging → [transaction for commands] → handler → persistence/outbox", new Exercise(ExerciseKind.MultipleChoice, "Check your understanding", "Which choice best follows the lesson?", ["Choose one answer"], null, "correct", [new Choice("correct", "Design a test proving a failed command rolls back both the aggregate write and outbox event."), new Choice("incorrect", "Bypass the layer boundary to make a controller or handler compile."), new Choice("other", "Ignore the rule and rely on the UI to enforce it.")], "Choose the design that preserves the appropriate boundary and explicitly handles failures.", ["Explains the design tradeoff"]), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/ef/core/saving/transactions")),
        new("api-thin-endpoints", "ASP.NET Core API design", 7, "Keep endpoints thin and HTTP-aware", "Endpoints translate between HTTP and your application; they should not make business decisions.", "An endpoint adapts untrusted HTTP input to an application request and maps the outcome to HTTP; it does not own domain decisions.", "An endpoint binds and validates the request, authorizes it, invokes one application use case (a handler or application service), maps the outcome to a DTO or status code, and returns. Do not place EF queries, domain conditionals or multi-step business logic in controllers. Never return an internal Result object over HTTP. Map created resources to 201, no body to 204, successful reads to 200, and documented failures to RFC 9457-style ProblemDetails. Minimal APIs may apply the same separation without controllers. All endpoints should accept CancellationToken and propagate it through the application layer and EF Core.", "[HttpGet(\"{id:guid}\")]\\npublic async Task<ActionResult<OrderDto>> Get(Guid id, CancellationToken ct)\\n    => Ok(await sender.Send(new GetOrder(id), ct));", new Exercise(ExerciseKind.Presentation, "Practice the design", "Refactor an endpoint that queries DbContext and applies a domain rule into an application request.", ["Work through the scenario before continuing", "Compare the alternatives and their consequences"], null, null, [], "Sketch the types and trace how a request flows across the boundaries.", []), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/aspnet/core/web-api/handle-errors")),
        new("api-authorization-input", "ASP.NET Core API design", 8, "Authorize and validate every boundary", "Treat every request as untrusted until it is authenticated, authorized and validated.", "Authentication identifies the caller; authorization decides if that caller can perform this operation. Query, route and body inputs are all untrusted.", "Make endpoints secure by default, for example with a fallback authorization policy that requires an authenticated user, and use [AllowAnonymous] or AllowAnonymous() only with documented intent. Enforce resource-level authorization on the server. Validate request DTO shape (with built-in validation, FluentValidation, or equivalent), including string limits, defined enums, numeric ranges, paging maximums and route IDs. Parameterize database calls; do not concatenate unsafe input or echo it into logs or HTML. Sanitization depends on output context: HTML encode on output rather than blindly deleting characters from legitimate input. Never log credentials, tokens or personal data.", "public sealed record SearchOrders(int Page, int PageSize);\\n// Page >= 1; PageSize between 1 and 100; check tenant authorization server-side.", new Exercise(ExerciseKind.MultipleChoice, "Check your understanding", "Which choice best follows the lesson?", ["Choose one answer"], null, "correct", [new Choice("correct", "Enumerate attacks against an uncapped query page size and an unauthorized resource ID."), new Choice("incorrect", "Bypass the layer boundary to make a controller or handler compile."), new Choice("other", "Ignore the rule and rely on the UI to enforce it.")], "Choose the design that preserves the appropriate boundary and explicitly handles failures.", ["Explains the design tradeoff"]), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/aspnet/core/security/authorization/introduction")),
        new("errors-results", "Errors & outcomes", 9, "Choose Result or exception by semantics", "Return a Result for outcomes callers must handle; throw for situations that should not happen.", "Result explicitly represents an expected alternative the caller must inspect. Exceptions represent unexpected failures or policy-selected error mapping, not routine branching.", "For single-outcome methods return the value/Task/void without wrapping it. Use Result when an expected recoverable branch requires a caller decision (such as inventory reservation rejected). In a mapped-exception style, missing resources throw NotFoundException; domain invariant violation throws DomainException with stable Code; a global handler maps these to ProblemDetails 404/409 and input validation to 400 or 422 as the API contract defines. Avoid treating every normal duplicate/missing lookup as an exception in code that must branch routinely. Do not catch a DomainException merely to rethrow it. Never expose exception stack traces in public responses.", "var order = await repository.FindAsync(id, ct)\\n    ?? throw new NotFoundException(\"order.not_found\");", new Exercise(ExerciseKind.Presentation, "Practice the design", "Compare a recoverable insufficient-stock outcome with a missing GET resource and choose the correct contract.", ["Work through the scenario before continuing", "Compare the alternatives and their consequences"], null, null, [], "Sketch the types and trace how a request flows across the boundaries.", []), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/aspnet/core/fundamentals/error-handling-api")),
        new("errors-fail-loudly", "Errors & outcomes", 10, "Fail loudly without accidental masking", "Code that hides failures turns small bugs into silent data corruption.", "A failure policy must distinguish a legitimate absence from a broken invariant or infrastructure failure.", "Avoid blanket try/catch that logs and continues, silent defaults that hide invalid state, and null-forgiving operators used to suppress actual uncertainty. Catch a specific exception only when you can recover, translate at an actual boundary, add non-sensitive context, or rethrow preserving stack trace. Use a global exception handler for consistent ProblemDetails and correlation IDs. Retry only transient, safe operations and preserve cancellation. Map concurrency conflict to 409 when appropriate.", "// Do not: catch (Exception) { return []; }\\n// Do: allow an unexpected persistence error to reach the exception handler.", new Exercise(ExerciseKind.MultipleChoice, "Check your understanding", "Which choice best follows the lesson?", ["Choose one answer"], null, "correct", [new Choice("correct", "Inspect a snippet with catch(Exception) returning an empty collection; explain why it is dangerous."), new Choice("incorrect", "Bypass the layer boundary to make a controller or handler compile."), new Choice("other", "Ignore the rule and rely on the UI to enforce it.")], "Choose the design that preserves the appropriate boundary and explicitly handles failures.", ["Explains the design tradeoff"]), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/dotnet/standard/exceptions/best-practices-for-exceptions")),
        new("csharp-di-time", "C# engineering conventions", 11, "Write explicit, testable C#", "Make dependencies, logging and the current time explicit so code is predictable and testable.", "Constructor injection provides dependencies to instances. TimeProvider supplies a controllable clock for deterministic time-dependent behavior.", "Prefer sealed classes unless inheritance is intentional; consider framework/proxy constraints. Use primary constructors where dependencies are simple. Reserve static for pure helpers/constants; keep I/O and dependencies in injected services. Use ILogger<T> for structured non-sensitive logs; do not use Console.Write as application logging. Inject TimeProvider at application boundaries and pass DateTimeOffset into domain methods rather than reading UtcNow inside aggregates. Avoid service locator outside composition code. Prefer DateTimeOffset for absolute instants and explicitly model time zones for local scheduling.", "public sealed class ExpireOrderHandler(TimeProvider clock, IOrderRepository orders)\\n{\\n    // pass clock.GetUtcNow() into order.ExpireAt(timestamp)\\n}", new Exercise(ExerciseKind.Presentation, "Practice the design", "Write a deterministic domain expiration test without reading the system clock.", ["Work through the scenario before continuing", "Compare the alternatives and their consequences"], null, null, [], "Sketch the types and trace how a request flows across the boundaries.", []), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/dotnet/standard/datetime/timeprovider-overview")),
        new("csharp-types-mapping-async", "C# engineering conventions", 12, "Make absence, mapping and asynchrony explicit", "Use the type system to make absence, state and asynchrony visible instead of implied.", "Nullable types represent genuine absence; enums or dedicated types represent mutually exclusive states. Mapping should transform shape, not decide business rules.", "Enable nullable reference analysis and fix warnings instead of suppressing them. Model optional fields only when legitimately optional; initialize collections to [] and expose IReadOnlyList<T>, IReadOnlyCollection<T> or immutable alternatives, using private mutable backing stores as needed. Avoid bool? state and string-as-flag decisions; use enums or sealed-record state hierarchies. Validate text with string.IsNullOrWhiteSpace when whitespace is invalid; otherwise use semantics appropriate to the domain. Explicit mapping methods and EF Select projections are easy to read, debug and refactor; mapping libraries remove boilerplate but hide mapping logic and move some errors to runtime (AutoMapper v15 and later are also commercially licensed). Choose with that tradeoff in mind. Avoid .Result, Wait(), GetAwaiter().GetResult(), async void outside event handlers, or Task.Run used to fake async I/O.", "public sealed record OrderDto(Guid Id, IReadOnlyList<OrderLineDto> Lines);\\n// EF read path: query.Select(o => new OrderDto(o.Id, ...))", new Exercise(ExerciseKind.MultipleChoice, "Check your understanding", "Which choice best follows the lesson?", ["Choose one answer"], null, "correct", [new Choice("correct", "Replace nested optional status strings with a typed state and write a pure DTO mapping."), new Choice("incorrect", "Bypass the layer boundary to make a controller or handler compile."), new Choice("other", "Ignore the rule and rely on the UI to enforce it.")], "Choose the design that preserves the appropriate boundary and explicitly handles failures.", ["Explains the design tradeoff"]), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/dotnet/csharp/nullable-references")),
        new("ef-query-hygiene", "EF Core & caching", 13, "Separate write aggregates and read projections", "Load whole aggregates to change data and project lean read models to display it.", "EF Core translates LINQ expressions into database queries. Query shape determines how many rows, columns and network calls are consumed.", "For reads use AsNoTracking(), Select into DTOs, a stable OrderBy, and Take with a server-enforced maximum; measure generated SQL. Avoid N+1 calls inside loops and unbounded Include graphs. For writes load tracked aggregate roots through a repository and persist within a transaction. Infrastructure owns DbContext and EF entities; Application contracts must not expose IQueryable or EF-specific objects. Use raw SQL only for a demonstrated limitation or measured performance case, comment why, and parameterize. Repositories fetch aggregates and preserve invariants; read-model query services may legitimately filter, sort and page—do not forbid ordering in all persistence components.", "await db.Orders.AsNoTracking().OrderBy(o => o.Id)\\n    .Take(50).Select(o => new OrderSummaryDto(o.Id, o.Status)).ToListAsync(ct);", new Exercise(ExerciseKind.Presentation, "Practice the design", "Identify an N+1 loop and replace it with a bounded projection, including a stable sort.", ["Work through the scenario before continuing", "Compare the alternatives and their consequences"], null, null, [], "Sketch the types and trace how a request flows across the boundaries.", []), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/ef/core/querying/tracking")),
        new("ef-cache-consistency", "EF Core & caching", 14, "Cache read models without breaking isolation", "A cache is a second copy of your data, so decide how stale it may be and who may see it.", "A cache trades freshness for faster repeated reads and must define correctness when data changes.", "Expose a cache port from Application; implement it in Infrastructure, never Domain. Cache DTOs/read models, not tracked EF entities or aggregate roots. Use an explicit TTL and an invalidation plan aligned with successful commands/commits (avoid eviction before rollback). Cache keys must include tenant, user/authorization scope, filters, page and representation version as needed. Design for races and distributed invalidation: eviction is not magically atomic with the database; versioned keys, outbox-driven invalidation or bounded staleness may be required. Choose expiration and cache failure behavior based on consistency requirements.", "orders:{tenantId}:{userId}:{status}:{page}:{version}", new Exercise(ExerciseKind.MultipleChoice, "Check your understanding", "Which choice best follows the lesson?", ["Choose one answer"], null, "correct", [new Choice("correct", "Design a tenant-isolated cache key and explain a stale-read race after an order update."), new Choice("incorrect", "Bypass the layer boundary to make a controller or handler compile."), new Choice("other", "Ignore the rule and rely on the UI to enforce it.")], "Choose the design that preserves the appropriate boundary and explicitly handles failures.", ["Explains the design tradeoff"]), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/aspnet/core/performance/caching/overview")),
        new("architecture-testing-capstone", "Architecture & verification", 15, "Prove architecture with executable tests", "Turn architecture rules into tests that fail the build when a boundary is crossed.", "Architecture tests verify reference boundaries; integration tests verify actual behavior across HTTP and persistence.", "Add architecture assertions that Domain references no Infrastructure, Application references no API or Infrastructure project, and controllers have no DbContext dependency. Unit test value objects and aggregate invariants; use WebApplicationFactory for HTTP/authorization/ProblemDetails integration tests and an actual compatible test database for EF queries, outbox, and optimistic concurrency. Test cache tenant isolation and invalidation. Enforce formatting, nullable analysis and test runs in CI. An architecture is not proven merely because folders have the right names.", "// Example intent: Types.InAssembly(domainAssembly).ShouldNot().HaveDependencyOn(\"Infrastructure\")", new Exercise(ExerciseKind.MultipleChoice, "Check your understanding", "Which choice best follows the lesson?", ["Choose one answer"], null, "correct", [new Choice("correct", "Build a small reference API: create an order, reject bad quantity, return 404 for unknown ID, and verify read projection, authorization and concurrency."), new Choice("incorrect", "Bypass the layer boundary to make a controller or handler compile."), new Choice("other", "Ignore the rule and rely on the UI to enforce it.")], "Choose the design that preserves the appropriate boundary and explicitly handles failures.", ["Explains the design tradeoff"]), null, new VersionStamp("C# 14", ".NET 10", "2026-10-21", "https://learn.microsoft.com/en-us/aspnet/core/test/integration-tests")),
